g.metadata:
{
  "schema": "ppt-master.semantic-table.v2",
  "name": "hurdle-vs-carry-table",
  "x": 64, "y": 262, "width": 1152, "height": 330,
  "strict_grid": true,
  "column_widths": [576, 576],
  "row_heights": [44, 88, 110, 88],
  "style": {
    "font_family": "Calibri",
    "font_size": 20,
    "header_fill": "#003657",
    "header_text": "#FBF8F2",
    "body_text": "#1E1E1E",
    "band_row": false,
    "valign": "middle"
  },
  "defaults": {
    "cell": {
      "padding": {"left": 16, "right": 16, "top": 6, "bottom": 6},
      "borders": {
        "left": {"style": "none"}, "right": {"style": "none"},
        "top": {"style": "solid", "color": "#D6CFC2", "width": 1},
        "bottom": {"style": "solid", "color": "#D6CFC2", "width": 1}
      }
    }
  },
  "columns": [
    {"text": "Hurdle rate", "bold": true, "align": "l"},
    {"text": "Reduction in carry", "bold": true, "align": "l"}
  ],
  "rows": [
    [
      {"paragraphs": [{"runs": [{"text": "What it does: ", "bold": true}, {"text": "investors receive the accrued preferred return before TPG earns carry. It does not guarantee that return."}]}]},
      {"paragraphs": [{"runs": [{"text": "What it does: ", "bold": true}, {"text": "TPG receives a smaller share of eligible profits, so investors retain more."}]}]}
    ],
    [
      {"paragraphs": [{"runs": [{"text": "Why catch-up matters: ", "bold": true}, {"text": "with full catch-up, TPG can recover its agreed profit share after investors receive the preference. Without catch-up, investors keep more of that benefit."}]}], "fill": "#F1ECE2"},
      {"paragraphs": [{"runs": [{"text": "What it does not do alone: ", "bold": true}, {"text": "it does not impose a minimum investor return before carry is paid."}]}], "fill": "#F1ECE2"}
    ],
    [
      {"paragraphs": [{"runs": [{"text": "Contemporary evidence: ", "bold": true}, {"text": "in the July 2007 sample, 93.1% of 144 buyout funds use hurdles and 8% is the most common rate."}]}]},
      {"paragraphs": [{"runs": [{"text": "Contemporary evidence: ", "bold": true}, {"text": "the same sample's terms table records no buyout funds with carry below 20%."}]}]}
    ]
  ]
}
